mapper.select:

where state in ('HORIZONTAL_APPLY_DRAFT','HORIZONTAL_APPLY_JYS_AUDIT','HORIZONTAL_APPLY_KYC_AUDIT','HORIZONTAL_APPLY_PASSED')
 and top_name like concat('%', #{topName}, '%')
 or top_number = #{topNumber}
 and user_name like concat('%', #{userName}, '%')
 and d.dept_name like concat('%', #{dname}, '%')
 and p.dept_name like concat('%', #{yname}, '%')
 and d.dept_id = #{dnameId}
 and p.dept_id = #{ynameId}
 and state = #{state}
 and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}

${params.dataScope}
order  by
case
when state = 'HORIZONTAL_APPLY_DRAFT' then 1
when state = 'HORIZONTAL_APPLY_JYS_AUDIT' then 2
when state = 'HORIZONTAL_APPLY_KYC_AUDIT' then 3
when state = 'HORIZONTAL_APPLY_PASSED' then 4
else 5
end,
createtime desc

where 1=1 and s.state not like 'HORIZONTAL_OVER_%'
and s.state = #{state} and s.top_name like concat('%', #{topName}, '%') and s.top_number = #{topNumber} and u.user_name like concat('%', #{userName}, '%') and d.dept_name like concat('%', #{dname}, '%') and p.dept_name like concat('%', #{yname}, '%') and d.dept_id = #{dnameId} and p.dept_id = #{ynameId} and YEAR(DATE_ADD(s.signing_data,INTERVAL 1 MONTH)) = #{year}
${params.dataScope} order by case when s.state = 'HORIZONTAL_APPLY_DRAFT' then 1 when s.state = 'HORIZONTAL_APPLY_JYS_AUDIT' then 2 when s.state = 'HORIZONTAL_APPLY_KYC_AUDIT' then 3 when s.state = 'HORIZONTAL_APPLY_PASSED' then 4 when s.state = 'HORIZONTAL_OVER_DRAFT' then 5 when s.state = 'HORIZONTAL_OVER_JYS_AUDIT' then 6 when s.state = 'HORIZONTAL_OVER_KYC_AUDIT' then 7 when s.state = 'HORIZONTAL_OVER_PASSED' then 8 else 9 end, s.createtime desc

select #{uid} uid,s.id,u.user_name userName,s.top_number ,d.dept_id,d.dept_name dname,p.dept_id ynameId,p.dept_name yname, s.user_id, s.top_name, s.top_type,s.party_A,s.party_B, s.first_person_id,  s.second_person_id, s.third_person_id, fourth_person_id, s.signing_data, s.validity_Date,  concat( s.amount,'万') amount, s.contract, s.filing, s.state
from sci_horizontal_apply s
left join sys_user u on  s.user_id=u.user_id
left join sys_dept d on u.dept_id = d.dept_id
left join sys_dept p on d.parent_id =p.dept_id
where 1=1
 and top_name like concat('%', #{topName}, '%')
 and user_name like concat('%', #{userName}, '%')
 and d.dept_name like concat('%', #{dname}, '%')
 and p.dept_name like concat('%', #{yname}, '%')
 and d.dept_id = #{dnameId}
 and p.dept_id = #{ynameId}
 and state = #{state}
 and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}
${params.dataScope}
order  by createtime desc

