select s.id, u.user_id as participant_user_id, p.dept_name yname, d.dept_name dname, u.login_name, u.user_name userName, u.adminstrative_title, u.social_title, u.tea_zhicheng, s.top_name , sp.ranking, s.party_A, s.party_B, concat( s.amount, '万') amount, sush.change_value, sush.change_status, s.signing_data, s.validity_Date, s.state from sci_horizontal_apply s left join sys_user u on (s.second_person_id = u.user_id or s.first_person_id=u.user_id or s.third_person_id=u.user_id or s.fourth_person_id=u.user_id ) left join sys_dept d on u.dept_id = d.dept_id left join sys_dept p on d.parent_id = p.dept_id left join sci_user_score_history sush on (s.id = sush.apply_id and u.user_id=sush.user_id) left join sci_persion sp on (s.id=sp.apply_id and u.user_id=sp.persion_id) where 1=1
AND p.dept_id = #{college}
AND d.dept_id = #{major}
AND u.user_id = #{teacherName}
and s.createtime >= #{startTime}
and s.createtime <= #{endTime}
and s.top_name like concat('%', #{topicName}, '%')
AND s.state in (3,5,9,10,12,14,4,15,16)
AND s.state in (1,2,7,8,11,13)
AND s.state in (6)
AND (YEAR(DATE_ADD(s.signing_data, INTERVAL 1 MONTH)) = #{year} OR YEAR(DATE_ADD(s.validity_Date, INTERVAL 1 MONTH)) = #{year})
${_dataScope}
and s.top_name is not null and sush.change_status is not NULL order by yname asc, dname asc, u.login_name asc

